<?php
namespace App\Console\Commands;use App\Models\{NewsArticle,User};use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
class NotifyLatestNews extends Command{protected $signature='news:notify';protected $description='Create personalized career notifications';public function handle():int{$a=NewsArticle::where('is_published',true)->latest('published_at')->first();if(!$a)return self::SUCCESS;$n=0;User::where(fn($q)=>$q->where('role_code',1)->orWhere('role','student'))->with('candidateProfile.resumes')->chunkById(100,function($users)use($a,&$n){foreach($users as $u){$have=collect($u->candidateProfile?->resumes?->first()?->parsed_data['skills']??[]);$missing=collect($a->skills??[])->diff($have)->take(5)->values();DB::table('news_notifications')->updateOrInsert(['user_id'=>$u->id,'news_article_id'=>$a->id],['missing_skills'=>json_encode($missing),'message'=>$missing->isEmpty()?'This intelligence matches your skills.':'Consider learning: '.$missing->join(', '),'created_at'=>now(),'updated_at'=>now()]);$n++;}});$this->info("Notifications: $n");return self::SUCCESS;}}
